// about.tsx
"use client";
import React from 'react';

// TypeScript interface for type safety
interface AboutData {
  about_section: {
    title: string;
    description: string;
    image: string;
  };
  primary_color: string;
  secondary_color: string;
  accent_color: string;
  background_color: string;
  surface_color: string;
  text_color: string;
  text_muted: string;
  stats: Array<{ number: string; label: string }>;
  images: {
    gallery1: string;
    gallery2: string;
    gallery3: string;
  };
}


export default function About({ data }: { data: AboutData }) {
  // Helper for alpha-blended colors (e.g., #6366F1 + 30% opacity = #6366F130)
  const withAlpha = (color: string, alpha: string) => `${color}${alpha}`;
  console.log("STATS TYPE:", typeof data.stats);
  console.log("STATS VALUE:", data.stats);
  // Gallery data with labels
  const galleryItems = [
    { src: data.images.gallery1, label: 'Team Collaboration' },
    { src: data.images.gallery2, label: 'Global Summit' },
    { src: data.images.gallery3, label: 'Innovation Lab' },
  ];

  return (
    <section
      id="about"
      className="about-section"
      style={{
        padding: '5rem 2rem}}},
        backgroundColor: data.surface_color,
        position: 'relative}},
        overflow: 'hidden}},
        fontFamily: 'system-ui, -apple-system, sans-serif}},
      }}
    >
      {/* Background Decor */}
      <div
        style={{
          position: 'absolute}}},
          bottom: '-10%}},
          left: '-5%}},
          width: '500px}},
          height: '500px}},
          background: `radial-gradient(circle, ${withAlpha(data.secondary_color, '10')} 0%, transparent 70%)`,
          borderRadius: '50%}},
          zIndex: 0,
          filter: 'blur(80px)}},
          pointerEvents: 'none' as const,
        }}
        aria-hidden="true"
      />

      <div style={{
        maxWidth: '1200px}}},
        margin: '0 auto}},
        position: 'relative}},
        zIndex: 1,
      }}>
        {/* Section Header */}
        <div style={{
          textAlign: 'center}}},
          maxWidth: '800px}},
          margin: '0 auto 4rem}},
        }}>
          <span style={{
            color: data.secondary_color,
            fontWeight: '700}}},
            fontSize: '0.875rem}},
            textTransform: 'uppercase' as const,
            letterSpacing: '0.1em}},
            marginBottom: '1rem}},
            display: 'block}},
          }}>
            Our Story
          </span>
          <h2 style={{
            fontSize: 'clamp(2rem, 4vw, 3rem)}}},
            color: data.text_color,
            fontWeight: '800}},
            margin: '0 0 1.5rem}},
            lineHeight: 1.2,
          }}>
            {data.about_section.title}
          </h2>
          <p style={{
            color: data.text_muted,
            fontSize: '1.125rem}}},
            lineHeight: 1.7,
            margin: 0,
          }}>
            {data.about_section.description}
          </p>
        </div>

        {/* Main Content Split */}
        <div className="about-split" style={{
          display: 'grid}}},
          gridTemplateColumns: '1fr}},
          gap: '4rem}},
          alignItems: 'center}},
          marginBottom: '5rem}},
        }}>
          {/* Image Side */}
          <div style={{
            position: 'relative}}},
            borderRadius: '20px}},
            overflow: 'hidden}},
            boxShadow: `0 20px 50px -10px ${withAlpha(data.background_color, '80')}`,
            border: `1px solid ${data.background_color}`,
          }}>
            <img
              src={data.about_section.image}
              alt="Nexus Digital Team collaborating on digital transformation projects"
              style={{
                width: '100%}}},
                height: 'auto}},
                display: 'block}},
                objectFit: 'cover}},
                transition: 'transform 0.5s ease}},
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'scale(1.05)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'scale(1)';
              }}
              loading="lazy"
            />
            {/* Overlay Badge */}
            <div style={{
              position: 'absolute}}},
              bottom: '2rem}},
              left: '2rem}},
              padding: '1rem 1.5rem}},
              backgroundColor: data.background_color,
              borderRadius: '12px}},
              border: `1px solid ${data.surface_color}`,
              boxShadow: '0 10px 30px rgba(0,0,0,0.3)}},
            }}>
              <div style={}>
                2020
              </div>
              <div style={}>
                Founded
              </div>
            </div>
          </div>

          {/* Text Side */}
          <div style={{
            display: 'flex}}},
            flexDirection: 'column}},
            gap: '2rem}},
          }}>
            <div>
              <h3 style={{
                color: data.text_color,
                fontSize: '1.5rem}}},
                fontWeight: '700}},
                margin: '0 0 1rem}},
              }}>
                Democratizing Technology
              </h3>
              <p style={{
                color: data.text_muted,
                lineHeight: 1.7,
                margin: 0,
              }}}>
                We believe enterprise-grade AI and cloud solutions should be accessible to businesses of all sizes. Our mission is to bridge the gap between complex technology and practical business value.
              </p>
            </div>

            <div>
              <h3 style={{
                color: data.text_color,
                fontSize: '1.5rem}}},
                fontWeight: '700}},
                margin: '0 0 1rem}},
              }}>
                Global Impact
              </h3>
              <p style={{
                color: data.text_muted,
                lineHeight: 1.7,
                margin: 0,
              }}}>
                With a presence in over 30 countries, we bring diverse perspectives to every project. Our distributed team ensures 24/7 coverage and cultural adaptability for global enterprises.
              </p>
            </div>

            {/* Mini Stats */}
            <div style={{
              display: 'grid}}},
              gridTemplateColumns: 'repeat(2, 1fr)}},
              gap: '1.5rem}},
              paddingTop: '1rem}},
              borderTop: `1px solid ${data.background_color}`,
            }}>
              <div>
                <div style={}>
                  {data.stats[0]?.number}
                </div>
                <div style={}>
                  {data.stats[0]?.label}
                </div>
              </div>
              <div>
                <div style={}>
                  {data.stats[2]?.number}
                </div>
                <div style={}>
                  {data.stats[2]?.label}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Full Stats Bar */}
        <div style={{
          backgroundColor: data.background_color,
          borderRadius: '20px}}},
          padding: '3rem 2rem}},
          display: 'grid}},
          gridTemplateColumns: 'repeat(2, 1fr)}},
          gap: '2rem}},
          marginBottom: '5rem}},
        }}>
          {data.stats.map((stat, idx) => (
            <div
              key={stat.label}
              className="stat-card"
              style={{
                textAlign: 'center}}},
                padding: '1rem}},
                border: `1px solid ${data.surface_color}`,
                borderRadius: '12px}},
                transition: 'transform 0.2s, border-color 0.2s}},
                cursor: 'default}},
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'scale(1.05)';
                e.currentTarget.style.borderColor = data.primary_color;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'scale(1)';
                e.currentTarget.style.borderColor = data.surface_color;
              }}
            >
              <div style={{
                color: data.text_color,
                fontWeight: '800}}},
                fontSize: '2rem}},
                marginBottom: '0.5rem}},
                background: `linear-gradient(135deg, ${data.primary_color}, ${data.secondary_color})`,
                WebkitBackgroundClip: 'text}},
                WebkitTextFillColor: 'transparent}},
                backgroundClip: 'text' as const,
              }}>
                {stat.number}
              </div>
              <div style={}>
                {stat.label}
              </div>
            </div>
          ))}
        </div>

        {/* Gallery Grid */}
        <div style={}>
          <h3 style={{
            color: data.text_color,
            fontSize: '1.5rem}}},
            fontWeight: '700}},
            margin: '0 0 2rem}},
            textAlign: 'center}},
          }}>
            Life at Nexus
          </h3>
          <div className="gallery-grid" style={{
            display: 'grid}}},
            gridTemplateColumns: '1fr}},
            gap: '1.5rem}},
          }}>
            {galleryItems.map((item, idx) => (
              <div
                key={idx}
                className="gallery-item"
                style={{
                  position: 'relative}}},
                  borderRadius: '16px}},
                  overflow: 'hidden}},
                  aspectRatio: '4/3}},
                  border: `1px solid ${data.surface_color}`,
                }}
              >
                <img
                  src={item.src}
                  alt={item.label}
                  style={{
                    width: '100%}}},
                    height: '100%}},
                    objectFit: 'cover}},
                    transition: 'transform 0.5s ease}},
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'scale(1.1)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'scale(1)';
                  }}
                  loading="lazy"
                />
                <div
                  className="gallery-overlay"
                  style={{
                    position: 'absolute}}},
                    inset: 0,
                    background: `linear-gradient(to top, ${data.background_color}CC, transparent)`,
                    opacity: 0,
                    transition: 'opacity 0.3s ease}},
                    display: 'flex}},
                    alignItems: 'flex-end}},
                    padding: '1.5rem}},
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.opacity = '1';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.opacity = '0';
                  }}
                >
                  <span style={}>
                    {item.label}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Mission Highlight */}
        <div style={{
          backgroundColor: withAlpha(data.primary_color, '10'),
          border: `1px solid ${withAlpha(data.primary_color, '30')}}`,
          borderRadius: '20px}},
          padding: '3rem 2rem}},
          textAlign: 'center}},
          position: 'relative}},
          overflow: 'hidden}},
        }}>
          <div style={{
            position: 'absolute}}},
            top: 0,
            left: 0,
            right: 0,
            height: '4px}},
            background: `linear-gradient(90deg, ${data.primary_color}, ${data.secondary_color}, ${data.accent_color})`,
          }} />
          <h3 style={{
            color: data.text_color,
            fontSize: '1.75rem}}},
            fontWeight: '700}},
            margin: '0 0 1rem}},
          }}>
            "Transforming Tomorrow, Today"
          </h3>
          <p style={{
            color: data.text_muted,
            fontSize: '1.125rem}}},
            maxWidth: '600px}},
            margin: '0 auto}},
            lineHeight: 1.7,
          }}>
            Our commitment goes beyond code. We partner with you to build resilient, scalable, and future-proof digital ecosystems.
          </p>
        </div>
      </div>

      {/* CSS Animations & Responsive Styles */}
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          * { transition: none !important; animation: none !important; }
        }
        @media (min-width: 1024px) {
          .about-split {
            grid-template-columns: 1fr 1fr !important;
            gap: 5rem !important;
          }
        }
        @media (min-width: 768px) {
          .gallery-grid {
            grid-template-columns: repeat(3, 1fr) !important;
          }
        }
        @media (min-width: 768px) {
          .stat-card {
            grid-template-columns: repeat(4, 1fr) !important;
          }
        }
      `}</style>
    </section>
  );
}

