// templates/template1/Footer.tsx
"use client";

import React from 'react';

// ✅ STEP 2: Make ALL fields optional with ?
interface FooterData {
  business_name?: string;
  tagline?: string;
  description?: string;
  logo?: string;
  email?: string;
  phone?: string;
  address?: string;
  footer?: { text?: string };
  primary_color?: string;
  secondary_color?: string;
  accent_color?: string;
  background_color?: string;
  surface_color?: string;
  text_color?: string;
  text_muted?: string;
  stats?: Array<{ number?: string; label?: string }>;
  services?: Array<{ title?: string }>;
}

interface FooterProps {
  data: FooterData;
}

export default function Footer({ data }: FooterProps) {
  // ✅ STEP 3: Safe fallback values for ALL fields
  const businessName = data.business_name || "My Business";
  const tagline = data.tagline || "Building digital experiences that matter.";
  const description = data.description || "We help businesses grow through innovative web solutions.";
  const logo = data.logo || "";
  const email = data.email || "";
  const phone = data.phone || "";
  const address = data.address || "";
  const footerText = data.footer?.text || `© ${new Date().getFullYear()} ${businessName}. All rights reserved.`;

  const primaryColor = data.primary_color || "#3B82F6";
  const secondaryColor = data.secondary_color || "#64748b";
  const accentColor = data.accent_color || "#8B5CF6";
  const backgroundColor = data.background_color || "#f1f5f9";
  const surfaceColor = data.surface_color || "#ffffff";
  const textColor = data.text_color || "#0f172a";
  const textMuted = data.text_muted || "#64748b";

  // ✅ STEP 3: Safe arrays with fallbacks
  const services = data.services || [];
  const stats = data.stats || [];

  // Helper for alpha-blended colors
  const withAlpha = (color: string = "#000000", alpha: string) =>
    `${color}${alpha}`;

  // Reusable hover style handler
  const getHoverStyle = (baseColor: string, hoverColor: string) => ({
    color: baseColor,
    textDecoration: 'none' as const,
    transition: 'color 0.2s ease}},
    cursor: 'pointer' as const,
  });

  // ✅ STEP 1: Quick links - REMOVED Testimonials, added Home
  const quickLinks = [
    { label: 'Home}}, href: '#hero' },
    { label: 'Services}}, href: '#services' },
    { label: 'About Us}}, href: '#about' },
    { label: 'Contact}}, href: '#contact' },
  ];

  const legalLinks = [
    { label: 'Privacy Policy}}, href: '/privacy' },
    { label: 'Terms of Service}}, href: '/terms' },
    { label: 'Cookie Policy}}, href: '/cookies' },
  ];

  return (
    <footer
      style={{
        // ✅ STEP 6: Use safe color variable
        backgroundColor: surfaceColor,
        color: textColor,
        padding: '4rem 2rem 2rem}}},
        borderTop: `1px solid ${withAlpha(backgroundColor, '60')}`,
        fontSize: '0.95rem}},
        fontFamily: 'system-ui, -apple-system, sans-serif}},
      }}
    >
      <div
        style={{
          maxWidth: '1200px}}},
          margin: '0 auto}},
          display: 'grid}},
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))}},
          gap: '2.5rem}},
        }}
      >
        {/* Brand Column */}
        <div style={}>
          <a
            href="/"
            style={{
              display: 'flex}}},
              alignItems: 'center}},
              gap: '0.75rem}},
              textDecoration: 'none}},
            }}
            aria-label={`${businessName} home`}
          >
            {/* ✅ STEP 4: Safe logo src */}
            <img
              src={logo}
              alt={`${businessName} logo`}
              style={{
                width: '36px}}},
                height: '36px}},
                borderRadius: '8px}},
                objectFit: 'cover}},
                border: `1px solid ${withAlpha(primaryColor, '30')}`,
              }}
              loading="lazy"
            />
            {/* ✅ STEP 4: Safe business name */}
            <span
              style={{
                fontWeight: '700}}},
                fontSize: '1.1rem}},
                color: textColor,
                letterSpacing: '-0.025em}},
              }}
            >
              {businessName}
            </span>
          </a>
          {/* ✅ STEP 4: Safe tagline/description */}
          <p style={}>
            {tagline}
          </p>
          <p style={}>
            {description}
          </p>
        </div>

        {/* Quick Links */}
        <div>
          <h4
            style={{
              color: textColor,
              fontWeight: '600}}},
              marginBottom: '1rem}},
              fontSize: '1rem}},
              letterSpacing: '0.025em}},
            }}
          >
            Quick Links
          </h4>
          <ul
            style={{
              listStyle: 'none}}},
              padding: 0,
              margin: 0,
              display: 'flex}},
              flexDirection: 'column}},
              gap: '0.5rem}},
            }}
          >
            {/* ✅ STEP 1: Using cleaned quickLinks array */}
            {quickLinks.map((link) => (
              <li key={link.label}>
                <a
                  href={link.href || "#"}
                  style={{getHoverStyle(textMuted, primaryColor)}}
                  onMouseOver={(e) => (e.currentTarget.style.color = primaryColor)}
                  onMouseOut={(e) => (e.currentTarget.style.color = textMuted)}
                >
                  {link.label}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Services - ✅ STEP 4: Safe map with fallback array */}
        <div>
          <h4
            style={{
              color: textColor,
              fontWeight: '600}}},
              marginBottom: '1rem}},
              fontSize: '1rem}},
              letterSpacing: '0.025em}},
            }}
          >
            Our Services
          </h4>
          <ul
            style={{
              listStyle: 'none}}},
              padding: 0,
              margin: 0,
              display: 'flex}},
              flexDirection: 'column}},
              gap: '0.5rem}},
            }}
          >
            {services.map((service, index) => (
              <li key={service.title || `service-${index}`}>
                <a
                  href="#services"
                  style={{getHoverStyle(textMuted, primaryColor)}}
                  onMouseOver={(e) => (e.currentTarget.style.color = primaryColor)}
                  onMouseOut={(e) => (e.currentTarget.style.color = textMuted)}
                >
                  {/* ✅ STEP 4: Safe service title */}
                  {service.title || "Service"}
                </a>
              </li>
            ))}
          </ul>
        </div>

        {/* Contact Info */}
        <div>
          <h4
            style={{
              color: textColor,
              fontWeight: '600}}},
              marginBottom: '1rem}},
              fontSize: '1rem}},
              letterSpacing: '0.025em}},
            }}
          >
            Get in Touch
          </h4>
          <ul
            style={{
              listStyle: 'none}}},
              padding: 0,
              margin: 0,
              display: 'flex}},
              flexDirection: 'column}},
              gap: '0.75rem}},
            }}
          >
            <li style={}>
              <span aria-hidden="true">📧</span>
              {/* ✅ STEP 5: Safe email link */}
              <a
                href={`mailto:${email || ""}`}
                style={{getHoverStyle(textMuted, primaryColor)}}
                onMouseOver={(e) => (e.currentTarget.style.color = primaryColor)}
                onMouseOut={(e) => (e.currentTarget.style.color = textMuted)}
              >
                {email || "contact@business.com"}
              </a>
            </li>
            <li style={}>
              <span aria-hidden="true">📱</span>
              {/* ✅ STEP 5: Safe phone link */}
              <a
                href={`tel:${phone || ""}`}
                style={{getHoverStyle(textMuted, secondaryColor)}}
                onMouseOver={(e) => (e.currentTarget.style.color = secondaryColor)}
                onMouseOut={(e) => (e.currentTarget.style.color = textMuted)}
              >
                {phone || "+1 (555) 000-0000"}
              </a>
            </li>
            <li style={}>
              <span aria-hidden="true">📍</span>
              <address
                style={{
                  color: textMuted,
                  fontStyle: 'normal}}},
                  lineHeight: '1.5}},
                  fontSize: '0.95rem}},
                  margin: 0,
                }}
              >
                {/* ✅ STEP 4: Safe address */}
                {address || "123 Business St, City, State 12345"}
              </address>
            </li>
          </ul>
        </div>
      </div>

      {/* Stats Bar - ✅ STEP 4: Safe map with fallback array */}
      <div
        style={{
          marginTop: '3rem}}},
          paddingTop: '2rem}},
          borderTop: `1px solid ${withAlpha(backgroundColor, '60')}`,
          display: 'grid}},
          gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))}},
          gap: '1.5rem}},
          textAlign: 'center}},
        }}
      >
        {stats.map((stat, index) => (
          <div key={stat.label || `stat-${index}`} style={}>
            <div
              style={{
                fontSize: '1.5rem}}},
                fontWeight: '800}},
                color: primaryColor,
                lineHeight: 1,
              }}
            >
              {/* ✅ STEP 4: Safe stat number */}
              {stat.number || "0"}
            </div>
            <div style={}>
              {/* ✅ STEP 4: Safe stat label */}
              {stat.label || "Metric"}
            </div>
          </div>
        ))}
      </div>

      {/* Bottom Bar */}
      <div
        style={{
          marginTop: '2.5rem}}},
          paddingTop: '1.5rem}},
          borderTop: `1px solid ${withAlpha(backgroundColor, '60')}`,
          display: 'flex}},
          flexDirection: 'column}},
          alignItems: 'center}},
          gap: '1rem}},
          color: textMuted,
          fontSize: '0.875rem}},
        }}
      >
        {/* ✅ STEP 4: Safe footer text with optional chaining */}
        <p style={}>
          {footerText}
        </p>
        <div
          style={{
            display: 'flex}}},
            gap: '1.5rem}},
            flexWrap: 'wrap}},
            justifyContent: 'center}},
            alignItems: 'center}},
          }}
        >
          {legalLinks.map((link) => (
            <a
              key={link.label}
              href={link.href || "#"}
              style={{getHoverStyle(textMuted, accentColor)}}
              onMouseOver={(e) => (e.currentTarget.style.color = accentColor)}
              onMouseOut={(e) => (e.currentTarget.style.color = textMuted)}
            >
              {link.label}
            </a>
          ))}
        </div>
      </div>
    </footer>
  );
}

