// templates/template1/Navbar.tsx
"use client";

import React, { useState, useEffect } from 'react';

// ✅ STEP 2: Make ALL fields optional with ?
interface NavData {
  business_name?: string;
  logo?: string;
  cta_primary?: string;
  cta_secondary?: string;
  primary_color?: string;
  secondary_color?: string;
  accent_color?: string;
  background_color?: string;
  surface_color?: string;
  text_color?: string;
  text_muted?: string;
}

interface NavProps {
  data: NavData;
}

// ✅ STEP 1: Component name MUST match import (Navbar, NOT Nav)
export default function Navbar({ data }: NavProps) {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // ✅ STEP 4: Fix withAlpha with default parameter
  const withAlpha = (color: string = "#000000", alpha: string) =>
    `${color}${alpha}`;

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll}}, handleScroll);
    return () => window.removeEventListener('scroll}}, handleScroll);
  }, []);

const navLinks = [
  { label: 'Home}}, href: '#hero' },
  { label: 'About}}, href: '#about' },
  { label: 'Services}}, href: '#services' },
  { label: 'Contact}}, href: '#contact' },
];
  // ✅ STEP 3: Safe access with fallbacks for ALL data fields
  const businessName = data.business_name || "My Business";
  const logo = data.logo || "";
  const ctaPrimary = data.cta_primary || "Get Started";
  const ctaSecondary = data.cta_secondary || "Learn More";
  const primaryColor = data.primary_color || "#3B82F6";
  const backgroundColor = data.background_color || "#ffffff";
  const surfaceColor = data.surface_color || "#f8fafc";
  const textColor = data.text_color || "#0f172a";
  const textMuted = data.text_muted || "#64748b";

  return (
    <nav
      className="navbar"
      style={{
        position: 'sticky' as const,
        top: 0,
        zIndex: 1000,
        padding: '1rem 2rem}}},
        backgroundColor: isScrolled ? withAlpha(backgroundColor, 'F5') : 'transparent}},
        backdropFilter: isScrolled ? 'blur(12px)' : 'none}},
        borderBottom: isScrolled ? `1px solid ${withAlpha(surfaceColor, '40')}` : 'none}},
        transition: 'background-color 0.3s, backdrop-filter 0.3s, border-color 0.3s}},
        fontFamily: 'system-ui, -apple-system, sans-serif}},
      }}
    >
      <div
        style={{
          maxWidth: '1200px}}},
          margin: '0 auto}},
          display: 'flex}},
          justifyContent: 'space-between}},
          alignItems: 'center}},
        }}
      >
        {/* Logo */}
        <a
          href="/"
          style={{
            display: 'flex}}},
            alignItems: 'center}},
            gap: '0.75rem}},
            textDecoration: 'none}},
          }}
          // ✅ STEP 6: Safe alt text
          aria-label={`${businessName} home`}
        >
          <img
            // ✅ STEP 3: Safe src with fallback
            src={logo}
            // ✅ STEP 6: Safe alt with fallback
            alt={`${businessName} logo`}
            style={{
              width: '40px}}},
              height: '40px}},
              borderRadius: '8px}},
              objectFit: 'cover}},
              border: `1px solid ${withAlpha(primaryColor, '30')}`,
            }}
            loading="eager"
          />
          <span
            style={{
              fontWeight: '700}}},
              fontSize: '1.25rem}},
              color: textColor,
              letterSpacing: '-0.025em}},
            }}
          >
            {/* ✅ STEP 3: Safe business name */}
            {businessName}
          </span>
        </a>

        {/* Desktop Navigation Links */}
        <div
          className="nav-links-desktop"
          style={{
            display: 'none}}},
            alignItems: 'center}},
            gap: '2rem}},
          }}
        >
          {navLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              style={{
                color: textMuted,
                textDecoration: 'none}}},
                fontWeight: '500}},
                fontSize: '0.95rem}},
                transition: 'color 0.2s ease}},
                position: 'relative' as const,
                padding: '0.5rem 0}},
              }}
              onMouseOver={(e) => {
                e.currentTarget.style.color = primaryColor;
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.color = textMuted;
              }}
            >
              {link.label}
              <span
                style={{
                  position: 'absolute' as const,
                  bottom: 0,
                  left: 0,
                  width: '100%}}},
                  height: '2px}},
                  backgroundColor: primaryColor,
                  transform: 'scaleX(0)}},
                  transformOrigin: 'left}},
                  transition: 'transform 0.2s ease}},
                  opacity: 0.8,
                }}
                className="nav-link-underline"
              />
            </a>
          ))}
        </div>

        {/* Desktop CTA Buttons */}
        <div
          className="nav-ctas-desktop"
          style={{
            display: 'none}}},
            alignItems: 'center}},
            gap: '1rem}},
          }}
        >
          <a
            href="#solutions"
            style={{
              color: textColor,
              textDecoration: 'none}}},
              fontWeight: '500}},
              fontSize: '0.95rem}},
              padding: '0.5rem 1rem}},
              borderRadius: '6px}},
              transition: 'background-color 0.2s}},
            }}
            onMouseOver={(e) => {
              e.currentTarget.style.backgroundColor = withAlpha(surfaceColor, '80');
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent';
            }}
          >
            {/* ✅ STEP 5: Safe CTA text */}
            {ctaSecondary}
          </a>
          <a
            href="#consultation"
            style={{
              backgroundColor: primaryColor,
              color: '#FFFFFF}}},
              textDecoration: 'none}},
              fontWeight: '600}},
              fontSize: '0.95rem}},
              padding: '0.75rem 1.5rem}},
              borderRadius: '8px}},
              boxShadow: `0 4px 14px ${withAlpha(primaryColor, '40')}`,
              transition: 'transform 0.2s, box-shadow 0.2s}},
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-2px)';
              e.currentTarget.style.boxShadow = `0 8px 25px ${withAlpha(primaryColor, '60')}`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translateY(0)';
              e.currentTarget.style.boxShadow = `0 4px 14px ${withAlpha(primaryColor, '40')}`;
            }}
          >
            {/* ✅ STEP 5: Safe CTA text */}
            {ctaPrimary}
          </a>
        </div>

        {/* Mobile Menu Button */}
        <button
          className="mobile-menu-toggle"
          aria-label="Toggle navigation menu"
          aria-expanded={isMobileMenuOpen}
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          style={{
            display: 'flex}}},
            alignItems: 'center}},
            justifyContent: 'center}},
            width: '44px}},
            height: '44px}},
            background: 'transparent}},
            border: `1px solid ${withAlpha(surfaceColor, '60')}`,
            borderRadius: '8px}},
            color: textColor,
            fontSize: '1.5rem}},
            cursor: 'pointer}},
            transition: 'background-color 0.2s, border-color 0.2s}},
          }}
          onMouseOver={(e) => {
            e.currentTarget.style.backgroundColor = withAlpha(surfaceColor, '40');
            e.currentTarget.style.borderColor = primaryColor;
          }}
          onMouseOut={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
            e.currentTarget.style.borderColor = withAlpha(surfaceColor, '60');
          }}
        >
          {isMobileMenuOpen ? '✕' : '☰'}
        </button>
      </div>

      {/* Mobile Menu Dropdown */}
      {isMobileMenuOpen && (
        <div
          className="mobile-menu"
          style={{
            position: 'absolute' as const,
            top: '100%}}},
            left: 0,
            right: 0,
            backgroundColor: surfaceColor,
            borderBottom: `1px solid ${withAlpha(backgroundColor, '60')}`,
            padding: '1.5rem 2rem}},
            display: 'flex}},
            flexDirection: 'column}},
            gap: '1rem}},
            boxShadow: '0 10px 40px rgba(0,0,0,0.3)}},
            animation: 'slideDown 0.2s ease}},
          }}
        >
          {navLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              onClick={() => setIsMobileMenuOpen(false)}
              style={{
                color: textColor,
                textDecoration: 'none}}},
                fontWeight: '500}},
                fontSize: '1.1rem}},
                padding: '0.75rem 0}},
                borderBottom: `1px solid ${withAlpha(backgroundColor, '40')}`,
                transition: 'color 0.2s, padding-left 0.2s}},
              }}
              onMouseOver={(e) => {
                e.currentTarget.style.color = primaryColor;
                e.currentTarget.style.paddingLeft = '0.5rem';
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.color = textColor;
                e.currentTarget.style.paddingLeft = '0';
              }}
            >
              {link.label}
            </a>
          ))}
          <div style={}>
            <a
              href="#solutions"
              onClick={() => setIsMobileMenuOpen(false)}
              style={{
                color: textColor,
                textDecoration: 'none}}},
                fontWeight: '500}},
                padding: '0.75rem 1rem}},
                borderRadius: '8px}},
                border: `1px solid ${withAlpha(surfaceColor, '80')}`,
                textAlign: 'center' as const,
                transition: 'background-color 0.2s}},
              }}
              onMouseOver={(e) => {
                e.currentTarget.style.backgroundColor = withAlpha(backgroundColor, '40');
              }}
              onMouseOut={(e) => {
                e.currentTarget.style.backgroundColor = 'transparent';
              }}
            >
              {ctaSecondary}
            </a>
            <a
              href="#consultation"
              onClick={() => setIsMobileMenuOpen(false)}
              style={{
                backgroundColor: primaryColor,
                color: '#FFFFFF}}},
                textDecoration: 'none}},
                fontWeight: '600}},
                padding: '0.75rem 1rem}},
                borderRadius: '8px}},
                textAlign: 'center' as const,
                boxShadow: `0 4px 14px ${withAlpha(primaryColor, '40')}`,
                transition: 'transform 0.2s}},
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
              }}
            >
              {ctaPrimary}
            </a>
          </div>
        </div>
      )}

      <style>{`
        @keyframes slideDown {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @media (prefers-reduced-motion: reduce) {
          * { animation: none !important; transition: none !important; }
        }
        @media (min-width: 1024px) {
          .nav-links-desktop { display: flex !important; }
          .nav-ctas-desktop { display: flex !important; }
          .mobile-menu-toggle { display: none !important; }
          .nav-link-underline:hover { transform: scaleX(1) !important; }
        }
        @media (max-width: 1023px) {
          .nav-links-desktop, .nav-ctas-desktop { display: none !important; }
        }
      `}</style>
    </nav>
  );
}

pages.src/components/ContactSection.tsx:
"use client";

import React, { FormEvent, useState } from 'react';

// ✅ STEP 1: Make ALL fields optional with ?
interface ContactData {
  primary_color?: string;
  secondary_color?: string;
  accent_color?: string;
  background_color?: string;
  surface_color?: string;
  text_color?: string;
  text_muted?: string;
  contact?: {
    email?: string;
    phone?: string;
    address?: string;
  };
}

// ✅ CRITICAL FIX: ContactProps MUST declare `data: ContactData`
interface ContactProps {
  data: ContactData;
}

// Form state interface
interface FormData {
  name: string;
  email: string;
  subject: string;
  message: string;
}

export default function Contact({ data }: ContactProps) {
  // ✅ STEP 2: Fix withAlpha with defaults for BOTH params
  const withAlpha = (color: string = "#000000", alpha: string = "20") =>
    `${color}${alpha}`;

  // ✅ STEP 3: Safe fallback values for ALL color fields
  const primaryColor = data.primary_color || "#3B82F6";
  const secondaryColor = data.secondary_color || "#64748b";
  const accentColor = data.accent_color || "#8B5CF6";
  const backgroundColor = data.background_color || "#ffffff";
  const surfaceColor = data.surface_color || "#f1f5f9";
  const textColor = data.text_color || "#0f172a";
  const textMuted = data.text_muted || "#64748b";

  // ✅ STEP 3: Safe contact info with optional chaining + fallbacks
  const email = data.contact?.email || "contact@business.com";
  const phone = data.contact?.phone || "+1 (555) 000-0000";
  const address = data.contact?.address || "123 Business St, City, State 12345";

  // Form state
  const [formData, setFormData] = useState<FormData>({
    name: "",
    email: "",
    subject: "",
    message: "",
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Handle input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { id, value } = e.target;
    setFormData(prev => ({ ...prev, [id]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 1500));
      console.log("Form submitted:", formData);
      alert("Thank you! We'll be in touch soon.");
      setFormData({ name: "", email: "", subject: "", message: "" });
    } catch (error) {
      console.error("Submission error:", error);
      alert("Something went wrong. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <section 
      id="contact"
      className="contact-section"
      style={{
        padding: "5rem 2rem",
        backgroundColor: backgroundColor,
        position: "relative",
        overflow: "hidden",
        fontFamily: "system-ui, -apple-system, sans-serif",
      }}}
    >
      {/* Background Decor */}
      <div 
        style={{
          position: "absolute",
          top: "10%",
          left: "-10%",
          width: "600px",
          height: "600px",
          background: `radial-gradient(circle, ${withAlpha(primaryColor, "10")}} 0%, transparent 70%)`,
          borderRadius: "50%",
          zIndex: 0,
          filter: "blur(80px)",
          pointerEvents: "none" as const,
        }}
        aria-hidden="true"
      />

      <div style={{
        maxWidth: "1200px",
        margin: "0 auto",
        position: "relative",
        zIndex: 1,
      }}}>
        {/* Section Header */}
        <div style={{
          textAlign: "center",
          maxWidth: "800px",
          margin: "0 auto 4rem",
        }}}>
          <span style={{
            color: primaryColor,
            fontWeight: "700",
            fontSize: "0.875rem",
            textTransform: "uppercase" as const,
            letterSpacing: "0.1em",
            marginBottom: "1rem",
            display: "block",
          }}}>
            Get In Touch
          </span>
          <h2 style={{
            fontSize: "clamp(2rem, 4vw, 3rem)",
            color: textColor,
            fontWeight: "800",
            margin: "0 0 1.5rem",
            lineHeight: 1.2,
          }}}>
            Let's Build Something Great
          </h2>
          <p style={{
            color: textMuted,
            fontSize: "1.125rem",
            lineHeight: 1.7,
            margin: 0,
          }}}>
            Ready to start your digital transformation? Our team is here to answer your questions.
          </p>
        </div>

        {/* Main Contact Grid */}
        <div className="contact-grid" style={{
          display: "grid",
          gridTemplateColumns: "1fr",
          gap: "4rem",
          marginBottom: "5rem",
        }}}>
          {/* Contact Form */}
          <div style={{
            backgroundColor: surfaceColor,
            borderRadius: "20px",
            padding: "2.5rem",
            border: `1px solid ${backgroundColor}}`,
            boxShadow: "0 20px 50px -10px rgba(0,0,0,0.3)",
          }}>
            <h3 style={{
              color: textColor,
              fontSize: "1.5rem",
              fontWeight: "700",
              margin: "0 0 2rem",
            }}}>
              Send us a Message
            </h3>
            <form onSubmit={handleSubmit} style={}>
              <div className="form-row" style={{
                display: "grid",
                gridTemplateColumns: "1fr",
                gap: "1.5rem",
              }}}>
                <div style={}>
                  <label htmlFor="name" style={}>Full Name</label>
                  <input 
                    id="name" type="text" placeholder="John Doe" 
                    value={formData.name} onChange={handleChange} required
                    style={{
                      padding: "0.875rem 1rem", backgroundColor: backgroundColor,
                      border: `1px solid ${backgroundColor}}`, borderRadius: "8px",
                      color: textColor, fontSize: "1rem", outline: "none",
                      transition: "border-color 0.2s",
                    }}
                    onFocus={(e) => e.currentTarget.style.borderColor = primaryColor}
                    onBlur={(e) => e.currentTarget.style.borderColor = backgroundColor}
                  />
                </div>
                <div style={}>
                  <label htmlFor="email" style={}>Email Address</label>
                  <input 
                    id="email" type="email" placeholder="john@company.com" 
                    value={formData.email} onChange={handleChange} required
                    style={{
                      padding: "0.875rem 1rem", backgroundColor: backgroundColor,
                      border: `1px solid ${backgroundColor}}`, borderRadius: "8px",
                      color: textColor, fontSize: "1rem", outline: "none",
                      transition: "border-color 0.2s",
                    }}
                    onFocus={(e) => e.currentTarget.style.borderColor = primaryColor}
                    onBlur={(e) => e.currentTarget.style.borderColor = backgroundColor}
                  />
                </div>
              </div>

              <div style={}>
                <label htmlFor="subject" style={}>Subject</label>
                <input 
                  id="subject" type="text" placeholder="Project Inquiry" 
                  value={formData.subject} onChange={handleChange} required
                  style={{
                    padding: "0.875rem 1rem", backgroundColor: backgroundColor,
                    border: `1px solid ${backgroundColor}}`, borderRadius: "8px",
                    color: textColor, fontSize: "1rem", outline: "none",
                    transition: "border-color 0.2s",
                  }}
                  onFocus={(e) => e.currentTarget.style.borderColor = primaryColor}
                  onBlur={(e) => e.currentTarget.style.borderColor = backgroundColor}
                />
              </div>

              <div style={}>
                <label htmlFor="message" style={}>Message</label>
                <textarea 
                  id="message" rows={5} placeholder="Tell us about your project..." 
                  value={formData.message} onChange={handleChange} required
                  style={{
                    padding: "0.875rem 1rem", backgroundColor: backgroundColor,
                    border: `1px solid ${backgroundColor}}`, borderRadius: "8px",
                    color: textColor, fontSize: "1rem", outline: "none",
                    resize: "vertical" as const, transition: "border-color 0.2s",
                    fontFamily: "inherit",
                  }}
                  onFocus={(e) => e.currentTarget.style.borderColor = primaryColor}
                  onBlur={(e) => e.currentTarget.style.borderColor = backgroundColor}
                />
              </div>

              <button 
                type="submit" disabled={isSubmitting}
                style={{
                  padding: "1rem 2rem", backgroundColor: primaryColor,
                  color: "#FFFFFF", border: "none", borderRadius: "8px",
                  fontSize: "1rem", fontWeight: "600",
                  cursor: isSubmitting ? "not-allowed" : "pointer",
                  boxShadow: `0 4px 14px ${withAlpha(primaryColor, "50")}}`,
                  transition: "transform 0.2s, box-shadow 0.2s, opacity 0.2s",
                  opacity: isSubmitting ? 0.7 : 1,
                  display: "flex", alignItems: "center", justifyContent: "center", gap: "0.5rem",
                }}
                onMouseEnter={(e) => {
                  if (!isSubmitting) {
                    e.currentTarget.style.transform = "translateY(-2px)";
                    e.currentTarget.style.boxShadow = `0 8px 25px ${withAlpha(primaryColor, "70")}`;
                  }
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = "translateY(0)";
                  e.currentTarget.style.boxShadow = `0 4px 14px ${withAlpha(primaryColor, "50")}`;
                }}
              >
                {isSubmitting ? (
                  <>
                    <span style={{ 
                      width: "16px", height: "16px", border: "2px solid #FFFFFF", 
                      borderTopColor: "transparent", borderRadius: "50%",
                      animation: "spin 0.8s linear infinite", display: "inline-block",
                    }}} />
                    Sending...
                  </>
                ) : "Send Message"}
              </button>
            </form>
          </div>

          {/* Contact Info Cards */}
          <div style={}>
            <div style={}>
              {/* Email Card */}
              <div style={{
                display: "flex", alignItems: "flex-start", gap: "1rem",
                padding: "1.5rem", backgroundColor: surfaceColor,
                borderRadius: "12px", border: `1px solid ${backgroundColor}}`,
                transition: "transform 0.2s, border-color 0.2s", cursor: "pointer",
              }}
                onMouseEnter={(e) => { e.currentTarget.style.transform = "translateX(5px)"; e.currentTarget.style.borderColor = primaryColor; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = "translateX(0)"; e.currentTarget.style.borderColor = backgroundColor; }}
              >
                <div style={{
                  minWidth: "40px", height: "40px", backgroundColor: withAlpha(primaryColor, "15"),
                  borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: "1.25rem", color: primaryColor, flexShrink: 0,
                }}}>📧</div>
                <div>
                  <h4 style={}>Email Us</h4>
                  <a 
                    href={`mailto:${email}`}
                    onMouseOver={(e) => e.currentTarget.style.color = primaryColor}
                    onMouseOut={(e) => e.currentTarget.style.color = textMuted}
                  >
                    {email}
                  </a>
                </div>
              </div>

              {/* Phone Card */}
              <div style={{
                display: "flex", alignItems: "flex-start", gap: "1rem",
                padding: "1.5rem", backgroundColor: surfaceColor,
                borderRadius: "12px", border: `1px solid ${backgroundColor}}`,
                transition: "transform 0.2s, border-color 0.2s", cursor: "pointer",
              }}
                onMouseEnter={(e) => { e.currentTarget.style.transform = "translateX(5px)"; e.currentTarget.style.borderColor = secondaryColor; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = "translateX(0)"; e.currentTarget.style.borderColor = backgroundColor; }}
              >
                <div style={{
                  minWidth: "40px", height: "40px", backgroundColor: withAlpha(secondaryColor, "15"),
                  borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: "1.25rem", color: secondaryColor, flexShrink: 0,
                }}}>📱</div>
                <div>
                  <h4 style={}>Call Us</h4>
                  <a 
                    href={`tel:${phone}`}
                    onMouseOver={(e) => e.currentTarget.style.color = secondaryColor}
                    onMouseOut={(e) => e.currentTarget.style.color = textMuted}
                  >
                    {phone}
                  </a>
                </div>
              </div>

              {/* Address Card */}
              <div style={{
                display: "flex", alignItems: "flex-start", gap: "1rem",
                padding: "1.5rem", backgroundColor: surfaceColor,
                borderRadius: "12px", border: `1px solid ${backgroundColor}}`,
                transition: "transform 0.2s, border-color 0.2s", cursor: "default",
              }}
                onMouseEnter={(e) => { e.currentTarget.style.transform = "translateX(5px)"; e.currentTarget.style.borderColor = accentColor; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = "translateX(0)"; e.currentTarget.style.borderColor = backgroundColor; }}
              >
                <div style={{
                  minWidth: "40px", height: "40px", backgroundColor: withAlpha(accentColor, "15"),
                  borderRadius: "8px", display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: "1.25rem", color: accentColor, flexShrink: 0,
                }}}>📍</div>
                <div>
                  <h4 style={}>Visit Us</h4>
                  <address style={}>
                    {address}
                  </address>
                </div>
              </div>
            </div>

            {/* Map Placeholder */}
            <div style={{
              flex: 1, backgroundColor: surfaceColor, borderRadius: "12px",
              border: `1px solid ${backgroundColor}}`, overflow: "hidden",
              position: "relative", minHeight: "250px",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <div style={{
                position: "absolute", inset: 0, backgroundColor: backgroundColor, opacity: 0.5,
                backgroundImage: `radial-gradient(${surfaceColor}} 1px, transparent 1px)`,
                backgroundSize: "20px 20px",
              }} />
              <div style={{
                position: "relative", zIndex: 1, textAlign: "center", padding: "1.5rem",
                backgroundColor: surfaceColor, borderRadius: "12px",
                border: `1px solid ${primaryColor}}`, boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
              }}>
                <div style= aria-hidden="true">🗺️</div>
                <div style={}>Interactive Map</div>
                <div style={}>San Francisco, CA</div>
              </div>
            </div>
          </div>
        </div>

        {/* FAQ Section */}
        <div style={{
          maxWidth: "800px", margin: "0 auto",
          borderTop: `1px solid ${surfaceColor}}`, paddingTop: "4rem",
        }}>
          <h3 style={}>
            Frequently Asked Questions
          </h3>
          <div className="faq-grid" style={}>
            {[
              { q: "What is your typical response time?", a: "We aim to respond within 24 hours during business days." },
              { q: "Do you offer free consultations?", a: "Yes, we offer a free 30-minute initial consultation." },
              { q: "What industries do you serve?", a: "We work across finance, healthcare, retail, and technology sectors." },
              { q: "Is my data secure?", a: "Absolutely. We are SOC 2 Type II certified and prioritize security." }
            ].map((faq, idx) => (
              <div key={idx} style={{
                padding: "1.5rem", backgroundColor: surfaceColor,
                borderRadius: "12px", border: `1px solid ${backgroundColor}}`,
              }}>
                <h4 style={}>{faq.q}</h4>
                <p style={}>{faq.a}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* CSS Animations */}
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @media (prefers-reduced-motion: reduce) {
          * { transition: none !important; animation: none !important; }
        }
        @media (min-width: 640px) { .form-row { grid-template-columns: 1fr 1fr !important; } }
        @media (min-width: 1024px) {
